css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: calc(var(--loader-size) * .34); position: relative; display: flex; gap: 2.5%; align-items: center; justify-content: flex-end; }
.loader .mic { position: absolute; left: 0; top: 18%; width: 12%; height: 64%; border-radius: 999px 999px 40% 40%; background: linear-gradient(var(--accent-2), var(--accent)); animation: voice-mic calc(var(--loader-speed) * 1.4) ease-in-out infinite; }
.loader .mic::after { content: ''; position: absolute; left: 20%; right: 20%; top: 104%; height: 22%; border-radius: 0 0 999px 999px; box-shadow: inset 0 -3px 0 var(--accent); }
.loader span { width: 8%; border-radius: 999px; background: linear-gradient(var(--accent-2), var(--accent)); animation: voice-wave calc(var(--loader-speed) * 1.1) ease-in-out infinite; }
.loader span:nth-of-type(1) { height: 34%; animation-delay: calc(var(--loader-speed) * -.9); }
.loader span:nth-of-type(2) { height: 58%; animation-delay: calc(var(--loader-speed) * -.75); }
.loader span:nth-of-type(3) { height: 88%; animation-delay: calc(var(--loader-speed) * -.6); }
.loader span:nth-of-type(4) { height: 100%; animation-delay: calc(var(--loader-speed) * -.45); }
.loader span:nth-of-type(5) { height: 88%; animation-delay: calc(var(--loader-speed) * -.3); }
.loader span:nth-of-type(6) { height: 58%; animation-delay: calc(var(--loader-speed) * -.15); }
.loader span:nth-of-type(7) { height: 34%; }
@keyframes voice-wave { 0%, 100% { transform: scaleY(.28); opacity: .55; } 50% { transform: scaleY(1); opacity: 1; } }
@keyframes voice-mic { 0%, 100% { transform: scale(1); box-shadow: 0 0 0 0 color-mix(in srgb, var(--accent) 45%, transparent); } 50% { transform: scale(1.06); box-shadow: 0 0 0 8px color-mix(in srgb, var(--accent) 0%, transparent); } }
